/**
 * Spec for the NOAA solar position port.
 *
 * TWO LAYERS OF DEFENCE, because "matches a table I generated" alone proves
 * nothing about the table:
 *
 *  1. A PINNED REFERENCE TABLE (36 rows: 3 city latitudes × solstices +
 *     equinoxes × 3 times of day). Generated by an independent Python port of
 *     the same published NOAA equations, itself sanity-checked against the
 *     textbook identities in layer 2 before pinning. Tolerance 0.01° — the
 *     two ports share equations, so anything past float noise is a port bug.
 *
 *  2. PUBLISHED PHYSICS the table cannot fake:
 *      - solar declination at the solstices = ±23.44° (the published axial
 *        tilt; NOAA's calculator shows 23.43x for 2026) — tolerance 0.05°;
 *      - |declination| < 0.5° on the equinoxes;
 *      - noon altitude = 90° − |lat − declination| — tolerance 0.05°;
 *      - noon sun is NORTH of Bengaluru and Hyderabad on the June solstice
 *        (both sit south of the Tropic of Cancer) and south of Delhi;
 *      - equinox sunrise bears due east: azimuth 90° ± 1.5° where the
 *        elevation crosses zero;
 *      - NOAA refraction: ≈ +0.56° at the horizon, ≈ +0.016° at 45°, 0 at 89°.
 *
 * All elevations here are GEOMETRIC (`elevationDeg`); refraction is asserted
 * separately so neither test can hide an error in the other.
 */

import { describe, expect, it } from 'vitest';

import { CITY_CENTROIDS, cityForPack } from './cities';
import { istToUtcMs, refractionDeg, solarPosition, utcMsToIst } from './solar';

interface RefRow {
  readonly city: string;
  /** DD-MM-YYYY, IST. */
  readonly date: string;
  readonly time: string;
  readonly azimuthDeg: number;
  readonly elevationDeg: number;
}

