function utcMsFor(ddmmyyyy: string, hhmm: string): number {
  const [dd, mm, yyyy] = ddmmyyyy.split('-').map(Number) as [number, number, number];
  const [h, m] = hhmm.split(':').map(Number) as [number, number];
  return istToUtcMs({ year: yyyy, month: mm, day: dd }, h * 60 + m);
}

function city(packId: string): { latDeg: number; lonDeg: number } {
  const c = cityForPack(packId);
  if (c === null) throw new Error(`no centroid for ${packId}`);
  return c;
}

const SOLSTICE_TILT_DEG = 23.44; // published obliquity of the ecliptic (2026: 23.436)

describe('solarPosition — pinned NOAA reference table', () => {
  it.each(REFERENCE)('$city $date $time IST', (row) => {
    const { latDeg, lonDeg } = city(row.city);
    const pos = solarPosition(utcMsFor(row.date, row.time), latDeg, lonDeg);
    expect(pos.azimuthDeg).toBeCloseTo(row.azimuthDeg, 2); // ±0.01°
    expect(pos.elevationDeg).toBeCloseTo(row.elevationDeg, 2);
  });
});

describe('solarPosition — published physics, not the table', () => {
  it('declination hits ±23.44° at the solstices and ~0° at the equinoxes', () => {
    const { latDeg, lonDeg } = city('blr');
    const jun = solarPosition(utcMsFor('21-06-2026', '12:30'), latDeg, lonDeg);
    const dec = solarPosition(utcMsFor('21-12-2026', '12:30'), latDeg, lonDeg);
    expect(Math.abs(jun.declinationDeg - SOLSTICE_TILT_DEG)).toBeLessThan(0.05);
    expect(Math.abs(dec.declinationDeg + SOLSTICE_TILT_DEG)).toBeLessThan(0.05);
    for (const date of ['20-03-2026', '23-09-2026']) {
      const eq = solarPosition(utcMsFor(date, '12:30'), latDeg, lonDeg);
      expect(Math.abs(eq.declinationDeg)).toBeLessThan(0.5);
    }
  });

  it('noon altitude = 90° − |lat − declination| at every city, every key date', () => {
    for (const c of CITY_CENTROIDS) {
      for (const date of ['20-03-2026', '21-06-2026', '23-09-2026', '21-12-2026']) {
        // Scan for solar noon at 1-minute resolution — IST noon is not solar noon.
        let best = { elevationDeg: -Infinity, declinationDeg: 0, azimuthDeg: 0 };
        for (let minutes = 10 * 60; minutes < 15 * 60; minutes++) {
          const [dd, mm, yyyy] = date.split('-').map(Number) as [number, number, number];
          const pos = solarPosition(
            istToUtcMs({ year: yyyy, month: mm, day: dd }, minutes),
            c.latDeg,
            c.lonDeg,
          );
          if (pos.elevationDeg > best.elevationDeg) best = pos;
        }
        const ideal = 90 - Math.abs(c.latDeg - best.declinationDeg);
        expect(Math.abs(best.elevationDeg - ideal)).toBeLessThan(0.05);
        // South of the Tropic of Cancer the June-solstice noon sun is NORTH.
        const sunNorth = best.azimuthDeg < 90 || best.azimuthDeg > 270;
        expect(sunNorth).toBe(c.latDeg < best.declinationDeg);
      }
    }
  });

  it('equinox sunrise bears due east (azimuth 90° ± 1.5° at the zero crossing)', () => {
    for (const c of CITY_CENTROIDS) {
      let crossed = false;
      for (let minutes = 5 * 60; minutes < 8 * 60; minutes++) {
        const pos = solarPosition(
          istToUtcMs({ year: 2026, month: 3, day: 20 }, minutes),
          c.latDeg,
          c.lonDeg,
        );
        if (pos.elevationDeg >= 0) {
          expect(Math.abs(pos.azimuthDeg - 90)).toBeLessThan(1.5);
          crossed = true;
          break;
        }
      }
      expect(crossed).toBe(true);
    }
  });

  it('morning elevation rises monotonically toward noon', () => {
    const { latDeg, lonDeg } = city('hyd');
    let prev = -Infinity;
    for (let minutes = 7 * 60; minutes <= 12 * 60; minutes += 30) {
      const pos = solarPosition(
        istToUtcMs({ year: 2026, month: 6, day: 21 }, minutes),
        latDeg,
        lonDeg,
      );
      expect(pos.elevationDeg).toBeGreaterThan(prev);
      prev = pos.elevationDeg;
    }
  });
});

describe('refractionDeg — NOAA piecewise correction', () => {
  it('≈ +0.56° at the horizon, ≈ +0.016° at 45°, 0 high overhead', () => {
    expect(refractionDeg(0.5)).toBeCloseTo(0.4167, 3);
    expect(refractionDeg(-0.5)).toBeCloseTo(0.5616, 3);
    expect(refractionDeg(45)).toBeCloseTo(0.0161, 3);
    expect(refractionDeg(89)).toBe(0);
  });

  it('apparentElevationDeg = geometric + refraction', () => {
    const { latDeg, lonDeg } = city('blr');
    const pos = solarPosition(utcMsFor('20-03-2026', '06:45'), latDeg, lonDeg);
    expect(pos.apparentElevationDeg).toBeCloseTo(
      pos.elevationDeg + refractionDeg(pos.elevationDeg),
      9,
    );
  });
});

describe('IST clock helpers', () => {
  it('istToUtcMs/utcMsToIst round-trip and honour the +5:30 offset', () => {
    const ms = istToUtcMs({ year: 2026, month: 6, day: 21 }, 12 * 60 + 30);
    // 12:30 IST = 07:00 UTC.
    expect(new Date(ms).toISOString()).toBe('2026-06-21T07:00:00.000Z');
    const back = utcMsToIst(ms);
    expect(back.date).toEqual({ year: 2026, month: 6, day: 21 });
    expect(back.minutesOfDay).toBe(750);
  });

  it('crosses midnight correctly (00:10 IST is the previous UTC day)', () => {
    const ms = istToUtcMs({ year: 2026, month: 1, day: 1 }, 10);
    expect(new Date(ms).toISOString()).toBe('2025-12-31T18:40:00.000Z');
    expect(utcMsToIst(ms).date).toEqual({ year: 2026, month: 1, day: 1 });
  });
});
